        "superseded_by": "D3",
        "reason": "Pod 重启测试触发 oom_restart_loss_1200（丢失 1,200 条待重试通知）证伪 inmem_exp_backoff",
        "source_step": "S3_async_retry_step_4"
      }
    ],
    "open_questions": [
      {
